LOCK TABLE public.members, public.jobs, public.job_recommendation_flags IN SHARE ROW EXCLUSIVE MODE;

-- Fail before fixture writes if a required non-defaulted column is omitted.
DO $schema$
DECLARE omitted_columns text;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid='public.members'::regclass
      AND attname='birth_date' AND atttypid='date'::regtype AND attnotnull
      AND NOT atthasdef AND NOT attisdropped AND attidentity='' AND attgenerated='') THEN
    RAISE EXCEPTION 'Expected members.birth_date DATE NOT NULL without default; no correction attempted';
  END IF;
  SELECT string_agg(a.attrelid::regclass::text || '.' || a.attname, ', ' ORDER BY a.attrelid, a.attnum)
  INTO omitted_columns
  FROM pg_attribute a JOIN (VALUES
    ('public.members'::regclass, ARRAY['id','member_code','full_name','center_code','phone_mobile_normalized','created_at','updated_at','birth_date']),
    ('public.jobs'::regclass, ARRAY['id','job_code','title','summary','location_text','work_date_text','status','center_code','created_at','updated_at']),
    ('public.job_recommendation_flags'::regclass, ARRAY['member_id','job_id','center_code','is_recommended','recommendation_level','created_at','updated_at'])
  ) AS targets(relid, inserted_columns) ON targets.relid=a.attrelid
  WHERE a.attnum>0 AND NOT a.attisdropped AND a.attnotnull AND NOT a.atthasdef
